import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../../../core/supabase/supabase_client.dart';import '../data/notifications_repository.dart';
class NotificationsPage extends StatefulWidget{const NotificationsPage({super.key});@override State<NotificationsPage>createState()=>_NotificationsPageState();}class _NotificationsPageState extends State<NotificationsPage>{final repo=NotificationsRepository(SupabaseClientProvider.client);List<Map<String,dynamic>>items=[];RealtimeChannel? channel;bool loading=true;String?error;@override void initState(){super.initState();_load();channel=repo.subscribe(_load);}@override void dispose(){if(channel!=null)SupabaseClientProvider.client.removeChannel(channel!);super.dispose();}Future<void>_load()async{try{final x=await repo.load();if(mounted)setState(()=>items=x);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}String label(String t)=>({'friend_request':'sent you a friend request','friend_accept':'accepted your friend request','like':'liked your post','comment':'commented on your post','comment_reply':'replied to your comment','follow':'started following you','message':'sent you a message'}[t]??'sent you a notification');@override Widget build(BuildContext context){final unread=items.where((x)=>x['is_read']!=true).length;return ListView(padding:const EdgeInsets.fromLTRB(16,18,16,110),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(26),gradient:const LinearGradient(colors:[Color(0xff171a3a),Color(0xff4630a5),Color(0xff14b8d4)]),boxShadow:const[BoxShadow(blurRadius:28,color:Color(0x302c1b69),offset:Offset(0,12))]),child:Row(children:[const Expanded(child:Text('Activity',style:TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.w900))),Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:Colors.white24,borderRadius:BorderRadius.circular(99)),child:Text(unread>0?'$unread unread':'All caught up',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800,fontSize:12))) ]),),Align(alignment:Alignment.centerRight,child:TextButton(onPressed:unread==0?null:()async{await repo.markAllRead();await _load();},child:const Text('Mark all read'))),if(error!=null)Text(error!,style:const TextStyle(color:Color(0xffb4233c))),if(loading)const Padding(padding:EdgeInsets.all(30),child:Center(child:CircularProgressIndicator())),if(!loading&&items.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('🔔\nNo notifications yet.'))),...items.map(_item)];}Widget _item(Map<String,dynamic>n){final s=n['sender']as Map<String,dynamic>?;final avatar='${s?['avatar_url']??''}';final read=n['is_read']==true;final created=DateTime.tryParse('${n['created_at']}');return InkWell(onTap:()async{await repo.markRead(n['id']);await _load();},child:Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:read?const Color(0x120f172a):const Color(0x664f46e5)),boxShadow:const[BoxShadow(blurRadius:16,color:Color(0x100f172a),offset:Offset(0,6))]),child:Row(children:[CircleAvatar(radius:23,backgroundImage:avatar.isNotEmpty?NetworkImage(avatar):null,child:avatar.isEmpty?const Icon(Icons.person):null),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${s?['display_name']??s?['username']??'Someone'} ${label('${n['type']}')}',style:const TextStyle(fontWeight:FontWeight.w650)),if(created!=null)Text('${created.hour.toString().padLeft(2,'0')}:${created.minute.toString().padLeft(2,'0')}',style:const TextStyle(fontSize:11,color:Colors.grey))])),if(!read)const Icon(Icons.circle,size:8,color:Color(0xff4f46e5))]));}}
